{
  "meta": {
    "name": "User App",
    "description": "A basic application to manage users and related data."
  },
  "entities": [
    {
      "name": "User",
      "ownable": false,
      "fields": [
        {
          "name": "firstName",
          "type": "string",
          "required": true,
          "label": "First Name"
        },
        {
          "name": "lastName",
          "type": "string",
          "required": true,
          "label": "Last Name"
        },
        {
          "name": "email",
          "type": "email",
          "required": true,
          "unique": true
        },
        {
          "name": "role",
          "type": "enum",
          "required": true,
          "enumValues": [
            "admin",
            "member"
          ],
          "default": "member"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "admin",
      "description": "Administrator role"
    },
    {
      "name": "member",
      "description": "Standard member role",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "admin",
      "entity": "User",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "member",
      "entity": "User",
      "actions": [
        "read"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Users",
      "route": "/users",
      "type": "list",
      "entity": "User",
      "access": [
        "admin"
      ],
      "fields": [
        "firstName",
        "lastName",
        "email",
        "role"
      ]
    },
    {
      "name": "New User",
      "route": "/users/new",
      "type": "form",
      "entity": "User",
      "access": [
        "admin"
      ]
    },
    {
      "name": "My Profile",
      "route": "/profile",
      "type": "form",
      "entity": "User",
      "access": [
        "admin",
        "member"
      ],
      "fields": [
        "firstName",
        "lastName",
        "email"
      ]
    }
  ],
  "plans": [],
  "businessRules": [
    {
      "type": "ownership",
      "id": "userOwnership",
      "entity": "User"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
